        // Snapping for Drawing Tools or Selection
        if (tool !== ToolType.HAND) {
            const raycaster = new THREE.Raycaster();
            const ndc = new THREE.Vector2((e.pointer.x) * 1, (e.pointer.y) * 1); // R3F pointer is -1 to 1
            raycaster.setFromCamera(ndc, camera);

            // Get ground intersection for fallback
            const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
            const target = new THREE.Vector3();
            raycaster.ray.intersectPlane(plane, target);

            // Geometry Snap
            const snap = getGeometrySnap(target, raycaster.ray, shapes, drawingManager.drawPoints, SNAP_THRESHOLD, e.intersections[0]);

            drawingManager.setSnapInfo(snap);
            drawingManager.setCursorPos(snap.position);

            // Guide creation update
            if (drawingManager.guideCreation.active) {
                 // The hook uses an effect on cursorPos, so updating cursorPos is enough
            }
        }
    }, [tool, handlePPMove, handleRotateMove, shapes, drawingManager, camera]);

    return (
       <>
          <color attach="background" args={['#f8fafc']} />
          <ambientLight intensity={0.7} />
          <directionalLight position={[10, 20, 10]} intensity={0.8} castShadow shadow-mapSize={[2048, 2048]} />
          <Grid infiniteGrid sectionSize={1} cellSize={0.1} sectionColor="#e2e8f0" cellColor="#f1f5f9" fadeDistance={50} />
          <CameraHandler view={currentView} onFinished={() => setCurrentView(null)} />

          {shapes.map(s => (
              <ShapeRenderer 
                  key={s.id} 
                  shape={s} 
                  isSelected={selectedIds.includes(s.id)}
                  hidden={tempShape?.id === s.id}
                  pushPullState={ppState}
                  pushPullHandlers={{ handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, handlePointerMove: handlePPMove }}
                  drawingHandlers={{ 
                      handlePointerDown: drawingManager.handlePointerDown, 
                      handlePointerUp: drawingManager.handlePointerUp, 
                      handleClick: drawingManager.handleClick,
                  }}
                  rotateHandlers={{ handleClick: handleRotateClick, handlePointerMove: handleRotateMove }}
                  setDraggingState={setIsShapeDragging}
                  onShapeRef={(id, ref) => shapeRefs.current[id] = ref}
                  shapeRefs={shapeRefs}
                  setAlignmentLines={setAlignmentLines}
              />
          ))}

          {tempShape && (
               <ShapeRenderer 
                  shape={tempShape} 
                  isSelected={true} 
                  pushPullState={ppState} 
                  pushPullHandlers={{ handlePointerDown: ()=>{}, handlePointerUp: ()=>{}, handlePointerMove: ()=>{} }}
                  drawingHandlers={{ handlePointerDown: ()=>{}, handlePointerUp: ()=>{}, handleClick: ()=>{} }}
                  rotateHandlers={{ handleClick: ()=>{}, handlePointerMove: ()=>{} }}
                  setDraggingState={()=>{}}
                  onShapeRef={()=>{}}
                  shapeRefs={shapeRefs}
                  setAlignmentLines={()=>{}}
               />
          )}

          <InteractionLayer 
              shapes={shapes}
              tool={tool}
              setCursorPos={drawingManager.setCursorPos}
              setSnapInfo={drawingManager.setSnapInfo}
              cursorPos={drawingManager.cursorPos}
              snapInfo={drawingManager.snapInfo}
              drawPoints={drawingManager.drawPoints}
              isDragging={drawingManager.isDragging}
              drawingHeight={drawingManager.drawingHeight}
              typedInput={drawingManager.typedInput}
              guideCreating={drawingManager.guideCreation}
              rotateState={rotateState}
              drawingNormal={drawingManager.drawingNormal}
              isGizmoDragging={isGizmoDragging}
              inferenceGuide={drawingManager.inferenceGuide}
              setInferenceGuide={drawingManager.setInferenceGuide}
              onMove={onScenePointerMove}
              onPointerDown={drawingManager.handlePointerDown}
              onPointerUp={drawingManager.handlePointerUp}
              onClick={drawingManager.handleClick}
          />

          <GuideLinesRenderer lines={guideLines} />
          <AlignmentLinesRenderer lines={alignmentLines} />
          <SelectionGizmo setDragging={setIsGizmoDragging} />

          <OrbitControls 
              makeDefault 
              enabled={tool === ToolType.HAND || (!drawingManager.isDragging && !isPPDragging && !isGizmoDragging && !rotateState.startVector && !isShapeDragging)} 
              minPolarAngle={0} 
              maxPolarAngle={Math.PI / 2} 
          />

          <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
              <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" />
          </GizmoHelper>
       </>
    );
};

