// ... (retain useRotateManager, useDrawingManager, SceneContent, Viewport) ...
const useRotateManager = (shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>) => {
    // ... (code identical to previous version) ...
    const { tool, shapes, updateShapes, selectedIds, setMeasurement } = useApp();
    const { camera, gl } = useThree();
    const [rotateState, setRotateState] = useState<RotateState>({ phase: 'hover', pivot: null, axis: null, startVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null });

    useEffect(() => {
        if (tool !== ToolType.ROTATE) {
            setRotateState({ phase: 'hover', pivot: null, axis: null, startVector: null, currentAngle: 0, initialTransforms: {}, lockedAxis: null });
        }
    }, [tool]);

    useEffect(() => {
        if (tool !== ToolType.ROTATE) return;
        if (rotateState.phase === 'hover') { setMeasurement("旋轉模式：請點擊畫面設定「旋轉中心點」 (適用於單一物件或群組)"); } 
        else if (rotateState.phase === 'set-start') { setMeasurement("旋轉模式：請點擊設定「起始角度參考點」"); } 
        else if (rotateState.phase === 'rotating') { const deg = Math.round((rotateState.currentAngle * 180) / Math.PI); setMeasurement(`旋轉角度: ${deg}° (按住 Shift 可鎖定 15°)`); }
    }, [tool, rotateState.phase, rotateState.currentAngle, setMeasurement]);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (tool !== ToolType.ROTATE) return;
        e.stopPropagation();
        if (rotateState.phase === 'hover') {
             const point = e.point.clone();
             const initials: Record<string, {pos: THREE.Vector3, quat: THREE.Quaternion}> = {};
             shapes.filter(s => selectedIds.includes(s.id)).forEach(s => {
                 const obj = new THREE.Object3D();
                 obj.position.set(...s.position);
                 obj.rotation.set(...s.rotation);
                 obj.scale.set(...s.scale);
                 initials[s.id] = { pos: obj.position.clone(), quat: obj.quaternion.clone() };
             });
             setRotateState(prev => ({ ...prev, phase: 'set-start', pivot: point, initialTransforms: initials }));
        } else if (rotateState.phase === 'set-start') {
             const current = e.point.clone();
             if (rotateState.pivot) {
                 const startVec = new THREE.Vector3().subVectors(current, rotateState.pivot).normalize();
                 setRotateState(prev => ({ ...prev, phase: 'rotating', startVector: startVec, currentAngle: 0 }));
             }
        } else if (rotateState.phase === 'rotating') {
             if (rotateState.pivot && rotateState.startVector) {
                 const angle = rotateState.currentAngle;
                 const updates = Object.keys(rotateState.initialTransforms).map(id => {
                     const init = rotateState.initialTransforms[id];
                     const pivot = rotateState.pivot!;
                     const v = new THREE.Vector3().subVectors(init.pos, pivot);
                     v.applyAxisAngle(new THREE.Vector3(0, 1, 0), angle);
                     const newPos = new THREE.Vector3().addVectors(pivot, v);
                     const q = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), angle);
                     q.multiply(init.quat);
                     const newEuler = new THREE.Euler().setFromQuaternion(q);
                     return { id, changes: { position: [newPos.x, newPos.y, newPos.z] as [number, number, number], rotation: [newEuler.x, newEuler.y, newEuler.z] as [number, number, number] } };
                 });
                 updateShapes(updates);
             }
             setRotateState(prev => ({ ...prev, phase: 'hover', pivot: null, startVector: null, currentAngle: 0 }));
        }
    }, [tool, rotateState, selectedIds, shapes, updateShapes]);

    const handleRotateMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.ROTATE) return;
        const current = e.point.clone();
        if (rotateState.phase === 'rotating' && rotateState.pivot && rotateState.startVector) {
             const currVec = new THREE.Vector3().subVectors(current, rotateState.pivot).normalize();
             let angle = Math.atan2(currVec.z, currVec.x) - Math.atan2(rotateState.startVector.z, rotateState.startVector.x);
             if (e.shiftKey) { const SNAP = Math.PI / 12; angle = Math.round(angle / SNAP) * SNAP; }
             setRotateState(prev => ({ ...prev, currentAngle: angle }));
             Object.keys(rotateState.initialTransforms).forEach(id => {
                 const ref = shapeRefs.current[id];
                 if (!ref) return;
                 const init = rotateState.initialTransforms[id];
                 const pivot = rotateState.pivot!;
                 const v = new THREE.Vector3().subVectors(init.pos, pivot);
                 v.applyAxisAngle(new THREE.Vector3(0, 1, 0), angle);
                 const newPos = new THREE.Vector3().addVectors(pivot, v);
                 const q = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), angle);
                 q.multiply(init.quat);
                 ref.position.copy(newPos);
                 ref.quaternion.copy(q);
             });
        }
    }, [tool, rotateState, shapeRefs]);
    return { rotateState, handleRotateMove, handleClick };
};

