        }
        if (tool === ToolType.DRAW_TEXT) {
             const newShape: IShape = { id: `text-${Date.now()}`, layerId: activeLayerId, type: 'text', name: '文字說明', points: [{ x: 0, y: 0, z: 0 }], position: [cursorPos.x, cursorPos.y, cursorPos.z], rotation: [-Math.PI/2, 0, 0], scale: [1, 1, 1], height: 0, color: '#000000', content: '文字', fontSize: 0.5 };
