                 const p1 = guideCreation.edge[0].clone(); const p2 = guideCreation.edge[1].clone(); if (Math.abs(p1.y - p2.y) < 0.01) { p1.y = cursorPos.y; p2.y = cursorPos.y; }
                 const edgeVec = new THREE.Vector3().subVectors(p2, p1); const v = new THREE.Vector3().subVectors(cursorPos, p1); const d = edgeVec.clone().normalize(); const projectedV = d.multiplyScalar(v.dot(d)); const rejection = new THREE.Vector3().subVectors(v, projectedV); const dist = rejection.length(); setMeasurement(`距離: ${formatValue(dist)}`);
