    }, [tool, drawPoints, typedInput, handleInputSubmit, setMeasurement, guideCreation]);
    return { drawPoints, cursorPos, snapInfo, setCursorPos, setSnapInfo, handlePointerDown, handlePointerUp, handleClick, isDragging, drawingHeight, typedInput, guideCreation, drawingNormal, inferenceGuide, setInferenceGuide };
};

