  formatValue: (val: number) => string;
  subscribeMeasurement: (callback: (val: string) => void) => () => void;
  setCurrentView: (view: string) => void;
}

const AppContext = createContext<IAppContext | null>(null);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // State definitions
  const [shapes, setShapes] = useState<IShape[]>([]);
  const [layers, setLayers] = useState<ILayer[]>([
    { id: 'layer-1', name: '預設圖層', visible: true, locked: false }
  ]);
  const [activeLayerId, setActiveLayerId] = useState('layer-1');
  const [guideLines, setGuideLines] = useState<IGuideLine[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [unit, setUnit] = useState<'m' | 'cm'>('m');
  const [projectName, setProjectName] = useState('');
  const [isLayerPanelOpen, setLayerPanelOpen] = useState(false);
  const [booleanModal, setBooleanModal] = useState<IBooleanModalState>({ open: false, base: null, cutters: [] });

  // History State
  const [history, setHistory] = useState<{shapes: IShape[], layers: ILayer[], guideLines: IGuideLine[]}[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // Measurement subscription
  const measurementListeners = useRef<((val: string) => void)[]>([]);

  const _commitState = useCallback((newShapes: IShape[], newLayers: ILayer[], newGuideLines: IGuideLine[]) => {
      const newState = { shapes: newShapes, layers: newLayers, guideLines: newGuideLines };
      setHistory(prev => {
          const newHistory = prev.slice(0, historyIndex + 1);
          return [...newHistory, newState];
      });
      setHistoryIndex(prev => prev + 1);

      setShapes(newShapes);
      setLayers(newLayers);
      setGuideLines(newGuideLines);
  }, [historyIndex]);

  // Initial state commit
  useEffect(() => {
    if (history.length === 0) {
        const initialState = { shapes: [], layers: [{ id: 'layer-1', name: '預設圖層', visible: true, locked: false }], guideLines: [] };
        setHistory([initialState]);
        setHistoryIndex(0);
    }
  }, []);

  const undo = useCallback(() => {
      if (historyIndex > 0) {
          const prevIndex = historyIndex - 1;
          const prevState = history[prevIndex];
          setShapes(prevState.shapes);
          setLayers(prevState.layers);
          setGuideLines(prevState.guideLines);
          setHistoryIndex(prevIndex);
          setSelectedIds([]);
      }
  }, [history, historyIndex]);

  const redo = useCallback(() => {
      if (historyIndex < history.length - 1) {
          const nextIndex = historyIndex + 1;
          const nextState = history[nextIndex];
          setShapes(nextState.shapes);
          setLayers(nextState.layers);
          setGuideLines(nextState.guideLines);
          setHistoryIndex(nextIndex);
          setSelectedIds([]);
      }
  }, [history, historyIndex]);

  const addAIShapes = useCallback((items: AIGeneratedItem[]) => {
      const newShapes: IShape[] = items.map((item, idx) => ({
          id: `ai-${Date.now()}-${idx}`,
          layerId: activeLayerId,
          type: 'solid',
          points: [
              { x: item.x - item.width/2, y: 0, z: item.z - item.depth/2 },
              { x: item.x + item.width/2, y: 0, z: item.z - item.depth/2 },
              { x: item.x + item.width/2, y: 0, z: item.z + item.depth/2 },
              { x: item.x - item.width/2, y: 0, z: item.z + item.depth/2 },
          ],
          height: item.height,
          color: item.color,
          position: [0, 0, 0],
          rotation: [0, 0, 0],
          scale: [1, 1, 1],
          name: item.name
      }));
      _commitState([...shapes, ...newShapes], layers, guideLines);
  }, [shapes, layers, guideLines, activeLayerId, _commitState]);

  const updateShape = useCallback((id: string, changes: Partial<IShape>) => {
      const newShapes = shapes.map(s => s.id === id ? { ...s, ...changes } : s);
      _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, _commitState]);

  const updateShapes = useCallback((updates: { id: string, changes: Partial<IShape> }[]) => {
