};

const DimensionShape: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const { formatValue, tool, updateShape } = useApp();
    const { camera, gl } = useThree();
    const [dragP3, setDragP3] = useState<THREE.Vector3 | null>(null);
    const draggingRef = useRef(false);
    const rafRef = useRef<number | null>(null);
    if (!shape.points || shape.points.length < 3) return null;
    if (!shape.points[0] || !shape.points[1] || !shape.points[2]) return null;
    const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
    const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
    const p3Source = dragP3 || new THREE.Vector3(shape.points[2].x, shape.points[2].y, shape.points[2].z);
    if (Math.abs(p1.y - p2.y) < 0.05) { p3Source.y = p1.y; }
    const v12 = new THREE.Vector3().subVectors(p2, p1);
    const v13 = new THREE.Vector3().subVectors(p3Source, p1);
    const lenSq = v12.lengthSq();
    const projection = lenSq > 0 ? v13.dot(v12) / lenSq : 0;
    const projectedPoint = p1.clone().add(v12.multiplyScalar(projection));
    const offsetVector = new THREE.Vector3().subVectors(p3Source, projectedPoint);
    const dimStart = p1.clone().add(offsetVector);
    const dimEnd = p2.clone().add(offsetVector);
    const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);
    const GAP_SIZE = 0.05; 
    const offsetDir = offsetVector.clone().normalize();
    const offsetLen = offsetVector.length();
    const useGap = offsetLen > GAP_SIZE * 1.5;
    const ext1Start = useGap ? p1.clone().add(offsetDir.clone().multiplyScalar(GAP_SIZE)) : p1;
    const ext2Start = useGap ? p2.clone().add(offsetDir.clone().multiplyScalar(GAP_SIZE)) : p2;
    const color = isSelected ? '#3b82f6' : (shape.color || '#333');
    const isSelectMode = tool === ToolType.SELECT;
    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (!isSelectMode) return;
        if (isSelected && e.button === 0) {
            e.stopPropagation(); draggingRef.current = true; document.body.style.cursor = 'grabbing';
            const handleWindowMove = (ev: PointerEvent) => {
                if (!draggingRef.current) return;
                if (rafRef.current) cancelAnimationFrame(rafRef.current);
                rafRef.current = requestAnimationFrame(() => {
                    const raycaster = new THREE.Raycaster();
                    const ndc = new THREE.Vector2((ev.clientX / gl.domElement.clientWidth) * 2 - 1, -(ev.clientY / gl.domElement.clientHeight) * 2 + 1);
                    raycaster.setFromCamera(ndc, camera);
                    let plane: THREE.Plane;
                    if (Math.abs(p1.y - p2.y) < 0.1) { plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -p1.y); } else { const normal = new THREE.Vector3(); camera.getWorldDirection(normal).negate(); plane = new THREE.Plane().setFromNormalAndCoplanarPoint(normal, p1); }
                    const target = new THREE.Vector3();
                    if (raycaster.ray.intersectPlane(plane, target)) { setDragP3(target); }
                });
            };
            const handleWindowUp = () => {
                if (draggingRef.current) {
                    draggingRef.current = false; document.body.style.cursor = 'default'; window.removeEventListener('pointermove', handleWindowMove); window.removeEventListener('pointerup', handleWindowUp); if (rafRef.current) cancelAnimationFrame(rafRef.current);
                    setDragP3((finalP3) => { if (finalP3) { const newPoints = [shape.points[0], shape.points[1], { x: finalP3.x, y: finalP3.y, z: finalP3.z }]; updateShape(shape.id, { points: newPoints }); } return null; });
                }
            };
            window.addEventListener('pointermove', handleWindowMove); window.addEventListener('pointerup', handleWindowUp);
        } else { e.stopPropagation(); onSelect(e); }
    };
    return ( <group onPointerDown={isSelectMode ? handlePointerDown : undefined} position={shape.position} rotation={shape.rotation} scale={shape.scale}><SimpleLine points={[dimStart, dimEnd]} color={color} depthTest={false} /><SimpleLine points={[ext1Start, dimStart]} color="#999" dashed depthTest={false} /><SimpleLine points={[ext2Start, dimEnd]} color="#999" dashed depthTest={false} /><mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} depthTest={false} /></mesh><mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} depthTest={false} /></mesh><DimensionLabel position={midPoint} text={formatValue(p1.distanceTo(p2))} color={color} /></group> );
};

const AlignmentLinesRenderer: React.FC<{ lines: AlignmentLine[] }> = ({ lines }) => { if (lines.length === 0) return null; return ( <group>{lines.map((line, i) => (<SimpleLine key={i} points={line} color="red" dashed lineWidth={2} depthTest={false} opacity={0.8} />))}</group> ); };

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid' || type === 'none') return null;
    let color = '#f59e0b'; let size = 0.08; let geometry = <sphereGeometry args={[size]} />;
    if (type === 'endpoint' || type === 'vertex') { color = '#10b981'; size = 0.12; geometry = <sphereGeometry args={[size]} />; } 
    else if (type === 'midpoint') { color = '#06b6d4'; size = 0.1; geometry = <coneGeometry args={[size, size * 2, 4]} />; } 
    else if (type === 'edge') { color = '#ef4444'; size = 0.06; geometry = <boxGeometry args={[size * 1.5, size * 1.5, size * 1.5]} />; } 
    else if (type === 'face') { color = '#3b82f6'; }
    return (
        <group position={position}>
            {type === 'face' ? ( <mesh rotation={[-Math.PI/2, 0, 0]}><planeGeometry args={[0.2, 0.2]} /><meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} /><lineSegments><edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} /><lineBasicMaterial color={color} depthTest={false} /></lineSegments></mesh> ) : ( <mesh>{geometry}<meshBasicMaterial color={color} depthTest={false} /></mesh> )}
            {type === 'edge' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#ef4444" lineWidth={3} depthTest={false} />)}
            {type === 'midpoint' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#06b6d4" lineWidth={3} depthTest={false} />)}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid' || type === 'none') return null;
    let displayType = ''; let bgColor = 'bg-slate-900/90'; let textColor = 'text-white'; let borderColor = 'border-white/20'; let icon = '';
    switch(type) {
        case 'vertex': case 'endpoint': displayType = '節點 (Node)'; bgColor = 'bg-emerald-600/95'; borderColor = 'border-emerald-300'; icon = '🔴'; break;
        case 'midpoint': displayType = '中心點 (Intersection)'; bgColor = 'bg-cyan-600/95'; borderColor = 'border-cyan-300'; icon = '📍'; break;
        case 'edge': displayType = '邊緣 (Edge)'; bgColor = 'bg-red-500/95'; borderColor = 'border-red-300'; icon = '📏'; break;
        case 'face': displayType = '表面 (Face)'; bgColor = 'bg-blue-600/95'; borderColor = 'border-blue-300'; icon = '⬜'; break;
