export default Viewport;

import React, { createContext, useContext, useState, useCallback, useRef, useEffect } from 'react';
import * as THREE from 'three';
import { 
  ToolType, 
  IShape, 
  ILayer, 
  IGuideLine, 
  AIGeneratedItem,
  IPoint
} from '../types';
import { 
  DEFAULT_HEIGHT, 
  DEFAULT_COLOR, 
  GRID_SIZE 
} from '../constants';

interface IBooleanModalState {
  open: boolean;
  base: IShape | null;
  cutters: IShape[];
}

interface IAppContext {
  tool: ToolType;
  setTool: (tool: ToolType) => void;
  shapes: IShape[];
  layers: ILayer[];
  guideLines: IGuideLine[];
  selectedIds: string[];
  unit: 'm' | 'cm';
  setUnit: (unit: 'm' | 'cm') => void;
  projectName: string;
  setProjectName: (name: string) => void;

  // Actions
  addAIShapes: (items: AIGeneratedItem[]) => void;
  updateShape: (id: string, changes: Partial<IShape>) => void;
  updateShapes: (updates: { id: string, changes: Partial<IShape> }[]) => void;
  removeSelected: () => void;
  copySelected: () => void;
  selectShape: (id: string, multi: boolean) => void;
  clearScene: () => void;
  clearGuideLines: () => void;

  // Grouping
  groupSelected: () => void;
  ungroupSelected: () => void;

  // Boolean Operations
  subtractSelected: () => void;
  booleanModal: IBooleanModalState;
  confirmBooleanOperation: (isContainer: boolean) => void;
  cancelBooleanOperation: () => void;

  // Layers
  activeLayerId: string;
  setActiveLayerId: (id: string) => void;
  addLayer: (name: string) => void;
  removeLayer: (id: string) => void;
  toggleLayerVisibility: (id: string) => void;
  updateLayerName: (id: string, name: string) => void;
  isLayerPanelOpen: boolean;
  setLayerPanelOpen: (open: boolean) => void;

  // History
  undo: () => void;
  redo: () => void;
  canUndo: boolean;
  canRedo: boolean;

  // File Ops
  saveProject: () => void;
  openProject: (file: File) => void;
  exportImage: () => void;

  // Utils
  formatValue: (val: number) => string;
  subscribeMeasurement: (callback: (val: string) => void) => () => void;
  setMeasurement: (val: string) => void;
  setCurrentView: (view: string) => void;
}

const AppContext = createContext<IAppContext | null>(null);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // State definitions
  const [shapes, setShapes] = useState<IShape[]>([]);
  const [layers, setLayers] = useState<ILayer[]>([
    { id: 'layer-1', name: '預設圖層', visible: true, locked: false }
  ]);
  const [activeLayerId, setActiveLayerId] = useState('layer-1');
  const [guideLines, setGuideLines] = useState<IGuideLine[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [unit, setUnit] = useState<'m' | 'cm'>('m');
  const [projectName, setProjectName] = useState('');
  const [isLayerPanelOpen, setLayerPanelOpen] = useState(false);
  const [booleanModal, setBooleanModal] = useState<IBooleanModalState>({ open: false, base: null, cutters: [] });

  // History State
  const [history, setHistory] = useState<{shapes: IShape[], layers: ILayer[], guideLines: IGuideLine[]}[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // Measurement subscription
  const measurementListeners = useRef<((val: string) => void)[]>([]);

  const _commitState = useCallback((newShapes: IShape[], newLayers: ILayer[], newGuideLines: IGuideLine[]) => {
      const newState = { shapes: newShapes, layers: newLayers, guideLines: newGuideLines };
      setHistory(prev => {
          const newHistory = prev.slice(0, historyIndex + 1);
          return [...newHistory, newState];
      });
      setHistoryIndex(prev => prev + 1);

      setShapes(newShapes);
      setLayers(newLayers);
      setGuideLines(newGuideLines);
  }, [historyIndex]);

  // Initial state commit
  useEffect(() => {
    if (history.length === 0) {
        const initialState = { shapes: [], layers: [{ id: 'layer-1', name: '預設圖層', visible: true, locked: false }], guideLines: [] };
        setHistory([initialState]);
        setHistoryIndex(0);
    }
  }, []);

  const undo = useCallback(() => {
      if (historyIndex > 0) {
          const prevIndex = historyIndex - 1;
          const prevState = history[prevIndex];
          setShapes(prevState.shapes);
          setLayers(prevState.layers);
          setGuideLines(prevState.guideLines);
          setHistoryIndex(prevIndex);
          setSelectedIds([]);
      }
  }, [history, historyIndex]);

  const redo = useCallback(() => {
      if (historyIndex < history.length - 1) {
          const nextIndex = historyIndex + 1;
          const nextState = history[nextIndex];
          setShapes(nextState.shapes);
          setLayers(nextState.layers);
          setGuideLines(nextState.guideLines);
          setHistoryIndex(nextIndex);
          setSelectedIds([]);
      }
  }, [history, historyIndex]);

  const addAIShapes = useCallback((items: AIGeneratedItem[]) => {
      const newShapes: IShape[] = items.map((item, idx) => ({
          id: `ai-${Date.now()}-${idx}`,
          layerId: activeLayerId,
          type: 'solid',
          points: [
              { x: item.x - item.width/2, y: 0, z: item.z - item.depth/2 },
              { x: item.x + item.width/2, y: 0, z: item.z - item.depth/2 },
              { x: item.x + item.width/2, y: 0, z: item.z + item.depth/2 },
              { x: item.x - item.width/2, y: 0, z: item.z + item.depth/2 },
          ],
          height: item.height,
          color: item.color,
          position: [0, 0, 0],
          rotation: [0, 0, 0],
          scale: [1, 1, 1],
          name: item.name
      }));
      _commitState([...shapes, ...newShapes], layers, guideLines);
  }, [shapes, layers, guideLines, activeLayerId, _commitState]);

  const updateShape = useCallback((id: string, changes: Partial<IShape>) => {
      const newShapes = shapes.map(s => s.id === id ? { ...s, ...changes } : s);
      _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, _commitState]);

  const updateShapes = useCallback((updates: { id: string, changes: Partial<IShape> }[]) => {
      const newShapes = shapes.map(s => {
          const update = updates.find(u => u.id === s.id);
          return update ? { ...s, ...update.changes } : s;
      });
      _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, _commitState]);

  const removeSelected = useCallback(() => {
      const newShapes = shapes.filter(s => !selectedIds.includes(s.id));
      _commitState(newShapes, layers, guideLines);
      setSelectedIds([]);
  }, [shapes, layers, guideLines, selectedIds, _commitState]);

  const copySelected = useCallback(() => {
      // Basic copy implementation
      const toCopy = shapes.filter(s => selectedIds.includes(s.id));
      const newShapes = toCopy.map(s => ({
          ...s,
          id: `copy-${Date.now()}-${s.id}`,
          position: [s.position[0] + 0.5, s.position[1], s.position[2] + 0.5] as [number, number, number],
          name: `${s.name} (複製)`
      }));
      _commitState([...shapes, ...newShapes], layers, guideLines);
      setSelectedIds(newShapes.map(s => s.id));
  }, [shapes, layers, guideLines, selectedIds, _commitState]);

  const selectShape = useCallback((id: string, multi: boolean) => {
      if (multi) {
          setSelectedIds(prev => prev.includes(id) ? prev.filter(pid => pid !== id) : [...prev, id]);
      } else {
          setSelectedIds([id]);
      }
  }, []);

  const clearScene = useCallback(() => {
      _commitState([], layers, []);
      setSelectedIds([]);
  }, [layers, _commitState]);

  const clearGuideLines = useCallback(() => {
      _commitState(shapes, layers, []);
  }, [shapes, layers, _commitState]);

  const groupSelected = useCallback(() => {
      if (selectedIds.length < 2) return;
      const groupId = `group-${Date.now()}`;
      const newShapes = shapes.map(s => selectedIds.includes(s.id) ? { ...s, groupId } : s);
      _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, selectedIds, _commitState]);

  const ungroupSelected = useCallback(() => {
      const newShapes = shapes.map(s => selectedIds.includes(s.id) ? { ...s, groupId: undefined } : s);
      _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, selectedIds, _commitState]);

  const subtractSelected = useCallback(() => {
      if (selectedIds.length < 2) return;
      // Assume first selected is base (or last selected? usually last selected is active)
      // Logic: Selected objects -> 1 Base, others are Cutters.
      // We open modal to ask user confirmation and type.
      const baseId = selectedIds[0]; // Simplification
      const base = shapes.find(s => s.id === baseId);
      const cutters = shapes.filter(s => selectedIds.includes(s.id) && s.id !== baseId);

      if (base && cutters.length > 0) {
          setBooleanModal({ open: true, base, cutters });
      }
  }, [shapes, selectedIds]);

  const confirmBooleanOperation = useCallback((isContainer: boolean) => {
      const { base, cutters } = booleanModal;
      if (!base || cutters.length === 0) {
          setBooleanModal({ open: false, base: null, cutters: [] });
          return;
      }

      // 2. Prepare Base Matrix for inverse transformation
      const baseObj = new THREE.Object3D();
      baseObj.position.set(...base.position);
      baseObj.rotation.set(...base.rotation);
      baseObj.scale.set(...base.scale);
      baseObj.updateMatrixWorld();
      const baseInvMatrix = baseObj.matrixWorld.clone().invert();

      // 3. Transform all cutters into Base's local coordinate system
      const newHoles: IPoint[][] = [...(base.holes || [])];

      cutters.forEach(cutter => {
          const cutterObj = new THREE.Object3D();
          cutterObj.position.set(...cutter.position);
          cutterObj.rotation.set(...cutter.rotation);
          cutterObj.scale.set(...cutter.scale);
          cutterObj.updateMatrixWorld();

          // Transform points
          const holePoly: IPoint[] = cutter.points.map(p => {
              const vec = new THREE.Vector3(p.x, 0, p.z);
              // To World
              vec.applyMatrix4(cutterObj.matrixWorld);
              // To Base Local
              vec.applyMatrix4(baseInvMatrix);
              return { x: vec.x, y: 0, z: vec.z };
          });

          newHoles.push(holePoly);
      });

      // 4. Update Base shape with new holes
      const updatedBase = {
          ...base,
          holes: newHoles
      };

      // 5. Prepare Final Shapes
      const cutterIds = cutters.map(c => c.id);

      // We must use the current `shapes` state for the final filter to ensure we don't revert other changes
      let finalShapes = shapes.filter(s => !cutterIds.includes(s.id) && s.id !== base.id);

      if (isContainer) {
          // If container, we keep cutters but modify them to be thin "floors"
          // This simulates the "blind hole" effect
          const newGroupId = base.groupId || `group-${Date.now()}`;
          updatedBase.groupId = newGroupId;

          const CONTAINER_BOTTOM_THICKNESS = 0.1; // 10cm bottom

          const bottoms: IShape[] = cutters.map(c => ({
              ...c,
              id: `bottom-${c.id}`,
              type: 'solid',
              height: CONTAINER_BOTTOM_THICKNESS, // Simulate stopping the push/pull before the end
              // Align with base bottom
              position: [c.position[0], base.position[1], c.position[2]] as [number, number, number], 
              name: `${c.name} (底)`,
              groupId: newGroupId, // Auto group with base
              layerId: base.layerId,
              color: base.color // Match base color for seamless look
          }));

          finalShapes = [...finalShapes, updatedBase, ...bottoms];
      } else {
          finalShapes = [...finalShapes, updatedBase];
      }

      _commitState(finalShapes, layers, guideLines);
      setSelectedIds([base.id]);
      setBooleanModal({ open: false, base: null, cutters: [] });

  }, [booleanModal, shapes, layers, guideLines, historyIndex, _commitState]);

  const cancelBooleanOperation = useCallback(() => {
      setBooleanModal({ open: false, base: null, cutters: [] });
  }, []);

  const addLayer = useCallback((name: string) => {
      const newLayer = { id: `layer-${Date.now()}`, name, visible: true, locked: false };
      _commitState(shapes, [...layers, newLayer], guideLines);
      setActiveLayerId(newLayer.id);
  }, [shapes, layers, guideLines, _commitState]);

  const removeLayer = useCallback((id: string) => {
      if (layers.length <= 1) return;
      const newLayers = layers.filter(l => l.id !== id);
      // Move shapes to default layer or delete? Assume delete for now or keep in limbo. 
      // Better: prevent delete if shapes exist or move to active.
      const fallbackId = newLayers[0].id;
      const newShapes = shapes.map(s => s.layerId === id ? { ...s, layerId: fallbackId } : s);
      _commitState(newShapes, newLayers, guideLines);
      if (activeLayerId === id) setActiveLayerId(fallbackId);
  }, [shapes, layers, guideLines, activeLayerId, _commitState]);

  const toggleLayerVisibility = useCallback((id: string) => {
      const newLayers = layers.map(l => l.id === id ? { ...l, visible: !l.visible } : l);
      // We don't commit history for visibility toggles usually, but let's do it for consistency or skip _commitState if valid
      setLayers(newLayers);
  }, [layers]);

  const updateLayerName = useCallback((id: string, name: string) => {
      const newLayers = layers.map(l => l.id === id ? { ...l, name } : l);
      setLayers(newLayers);
  }, [layers]);

  const saveProject = useCallback(() => {
      const data = JSON.stringify({ shapes, layers, guideLines, version: 1 }, null, 2);
      const blob = new Blob([data], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${projectName || 'project'}.json`;
      a.click();
  }, [shapes, layers, guideLines, projectName]);

  const openProject = useCallback((file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              const data = JSON.parse(e.target?.result as string);
              if (data.shapes && data.layers) {
                  _commitState(data.shapes, data.layers, data.guideLines || []);
              }
          } catch (err) {
              console.error(err);
              alert("無法開啟檔案");
          }
      };
      reader.readAsText(file);
  }, [_commitState]);

  const exportImage = useCallback(() => {
      // Logic to grab canvas data url
      const canvas = document.querySelector('canvas');
      if (canvas) {
          const url = canvas.toDataURL('image/png');
          const a = document.createElement('a');
          a.href = url;
          a.download = `${projectName || 'screenshot'}.png`;
          a.click();
      }
  }, [projectName]);

  const formatValue = useCallback((val: number) => {
      if (unit === 'cm') return `${(val * 100).toFixed(1)} cm`;
      return `${val.toFixed(3)} m`;
  }, [unit]);

  const subscribeMeasurement = useCallback((callback: (val: string) => void) => {
      measurementListeners.current.push(callback);
      return () => {
          measurementListeners.current = measurementListeners.current.filter(cb => cb !== callback);
      };
  }, []);

  const setMeasurement = useCallback((val: string) => {
      measurementListeners.current.forEach(listener => listener(val));
  }, []);

  const setCurrentView = useCallback((view: string) => {
      // This is a placeholder as actual camera control might need ref to controls or using event bus
      console.log('Set view', view);
  }, []);

  return (
    <AppContext.Provider value={{
      tool, setTool,
      shapes, layers, guideLines, selectedIds,
      unit, setUnit,
      projectName, setProjectName,
      addAIShapes, updateShape, updateShapes, removeSelected, copySelected, selectShape, clearScene, clearGuideLines,
      groupSelected, ungroupSelected, subtractSelected,
      booleanModal, confirmBooleanOperation, cancelBooleanOperation,
      activeLayerId, setActiveLayerId, addLayer, removeLayer, toggleLayerVisibility, updateLayerName,
      isLayerPanelOpen, setLayerPanelOpen,
      undo, redo, canUndo: historyIndex > 0, canRedo: historyIndex < history.length - 1,
      saveProject, openProject, exportImage,
      formatValue, subscribeMeasurement, setMeasurement, setCurrentView
    }}>
      {children}
    </AppContext.Provider>
  );
};

import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, TransformControls, Html, GizmoHelper, GizmoViewport, Text } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, IGuideLine } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.05; 
const ALIGN_THRESHOLD = 0.4; 
const SNAP_CULLING_DISTANCE = 15; 

// --- Helper Functions ---
const getLocalBasis = (normal: THREE.Vector3) => {
    const n = normal.clone().normalize();
    let up = new THREE.Vector3(0, 1, 0);
    if (Math.abs(n.dot(up)) > 0.99) up.set(0, 0, 1);
    const right = new THREE.Vector3().crossVectors(n, up).normalize();
    const top = new THREE.Vector3().crossVectors(right, n).normalize(); 
    return { right, top, normal: n };
};

type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';
type AlignmentLine = [THREE.Vector3, THREE.Vector3];

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string;
    snapEdge?: [THREE.Vector3, THREE.Vector3];
    normal?: THREE.Vector3;
}

interface InferenceGuide {
    type: 'x' | 'z';
    start: THREE.Vector3;
    end: THREE.Vector3;
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number;
}

interface RotateState {
    phase: 'hover' | 'set-start' | 'rotating';
    pivot: THREE.Vector3 | null;
    axis: THREE.Vector3 | null;
    startVector: THREE.Vector3 | null;
    currentAngle: number;
    initialTransforms: Record<string, { pos: THREE.Vector3, quat: THREE.Quaternion }>;
    lockedAxis: THREE.Vector3 | null;
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    hidden?: boolean;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerMove?: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    rotateHandlers: {
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
    onShapeRef: (id: string, ref: THREE.Group | null) => void;
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>;
    setAlignmentLines: (lines: AlignmentLine[]) => void;
}

const createThreeShape = (points: IPoint[], holes?: IPoint[][]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  if (holes && holes.length > 0) {
      holes.forEach(holePoints => {
          if (holePoints.length > 0) {
              const holePath = new THREE.Path();
              holePath.moveTo(holePoints[0].x, -holePoints[0].z);
              for (let i = 1; i < holePoints.length; i++) {
                  holePath.lineTo(holePoints[i].x, -holePoints[i].z);
              }
              holePath.closePath();
              shape.holes.push(holePath);
          }
      });
  }
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    if (!localP) return new THREE.Vector3();
    const v = new THREE.Vector3(localP.x, 0, localP.z);
    v.set(v.x * shape.scale[0], v.y * shape.scale[1], v.z * shape.scale[2]);
    const euler = new THREE.Euler(...shape.rotation);
    v.applyEuler(euler);
    v.add(new THREE.Vector3(...shape.position));
    return v;
};

const getShapeBounds = (shape: IShape, currentPos?: THREE.Vector3) => {
    const pos = currentPos || new THREE.Vector3(...shape.position);
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    const tempShape = { ...shape, position: [pos.x, pos.y, pos.z] as [number, number, number] };
    shape.points.forEach(p => {
         if (!p) return;
         const wp = transformPoint(p, tempShape as IShape);
         if(wp.x < minX) minX = wp.x;
         if(wp.x > maxX) maxX = wp.x;
         if(wp.z < minZ) minZ = wp.z;
         if(wp.z > maxZ) maxZ = wp.z;
    });
    return { minX, maxX, minZ, maxZ, centerX: (minX + maxX) / 2, centerZ: (minZ + maxZ) / 2, y: pos.y };
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
};

const getSegmentIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    if (!p1 || !p2 || !p3 || !p4) return null;
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < 1e-9) return null; 
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;
    const TOLERANCE = 1e-5;
    if (u >= -TOLERANCE && u <= 1 + TOLERANCE && v >= -TOLERANCE && v <= 1 + TOLERANCE) {
        return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
    }
    return null;
};

const isSamePoint = (p1: IPoint, p2: IPoint) => {
    if (!p1 || !p2) return false;
    return Math.abs(p1.x - p2.x) < 1e-4 && Math.abs(p1.z - p2.z) < 1e-4;
};

const cutPolygonBySegment = (polyPoints: IPoint[], lineStart: IPoint, lineEnd: IPoint): [IPoint[], IPoint[]] | null => {
    interface Intersection { point: IPoint; edgeIndex: number; dist: number; }
    const intersections: Intersection[] = [];
    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];
        if (!p1 || !p2) continue;
        const hit = getSegmentIntersection(p1, p2, lineStart, lineEnd);
        if (hit) {
            const dist = Math.sqrt((hit.x - lineStart.x)**2 + (hit.z - lineStart.z)**2);
            const duplicate = intersections.find(int => isSamePoint(int.point, hit));
            if (!duplicate) { intersections.push({ point: hit, edgeIndex: i, dist }); }
        }
    }
    if (intersections.length < 2) return null;
    intersections.sort((a, b) => a.dist - b.dist);
    const startHit = intersections[0];
    const endHit = intersections[intersections.length - 1];
    if (isSamePoint(startHit.point, endHit.point)) return null;
    const getPointsBetween = (startInt: Intersection, endInt: Intersection) => {
        const pts: IPoint[] = [startInt.point];
        let currIdx = startInt.edgeIndex;
        const stopEdgeIdx = endInt.edgeIndex;
        let loops = 0;
        while (currIdx !== stopEdgeIdx && loops < polyPoints.length * 2) {
            const nextVertexIdx = (currIdx + 1) % polyPoints.length;
            if (!isSamePoint(polyPoints[nextVertexIdx], startInt.point)) { pts.push(polyPoints[nextVertexIdx]); }
            currIdx = nextVertexIdx;
            loops++;
        }
        if (!isSamePoint(endInt.point, pts[pts.length - 1])) { pts.push(endInt.point); }
        return pts;
    };
    const polyA = getPointsBetween(startHit, endHit);
    const polyB = getPointsBetween(endHit, startHit);
    if (polyA.length < 3 || polyB.length < 3) return null;
    return [polyA, polyB];
};

const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge' && shape.type !== 'line') return null;
    if (shape.points.length >= 2) {
        if (!shape.points[0] || !shape.points[1]) return null;
        const p1 = transformPoint(shape.points[0], shape);
        const p2 = transformPoint(shape.points[1], shape);
        return [p1, p2];
    }
    return null;
};

const getGeometrySnap = (cursorPos: THREE.Vector3, ray: THREE.Ray, shapes: IShape[], activePoints: IPoint[] = [], threshold: number, intersectedObject?: THREE.Intersection): SnapResult => {
    let fallbackSnap: SnapResult;
    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;
    if (intersectedObject && shapeData) {
        let normal = new THREE.Vector3(0, 1, 0);
        if (intersectedObject.face) {
            const normalMatrix = new THREE.Matrix3().getNormalMatrix(intersectedObject.object.matrixWorld);
            normal = intersectedObject.face.normal.clone().applyMatrix3(normalMatrix).normalize();
        }
        fallbackSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id, normal };
    } else {
        fallbackSnap = {
            position: new THREE.Vector3(Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID, cursorPos.y, Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID),
            type: 'grid', distance: Infinity, normal: new THREE.Vector3(0, 1, 0)
        };
    }
    let bestVertexSnap: SnapResult | null = null;
    let bestEdgeSnap: SnapResult | null = null;
    let minVertexDist = threshold;
    let minEdgeDist = threshold;

    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        if (startPt) {
            const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
            const dist = ray.distanceToPoint(ptVec);
            if (dist < threshold * 1.5) {
                bestVertexSnap = { position: ptVec, type: 'endpoint', distance: dist, normal: new THREE.Vector3(0,1,0) };
                minVertexDist = dist;
            }
        }
    }

    const checkPoints = (points: IPoint[], shape: IShape, hasHeight: boolean, currentH: number) => {
        for (let i = 0; i < points.length; i++) {
            if (!points[i]) continue;
            const worldPt = transformPoint(points[i], shape);
            let dist = ray.distanceToPoint(worldPt);
            if (dist < minVertexDist) {
                bestVertexSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id, normal: new THREE.Vector3(0,1,0) };
                minVertexDist = dist;
            }
            if (hasHeight) {
                const worldPtTop = transformPoint(points[i], { ...shape, position: [shape.position[0], shape.position[1] + currentH, shape.position[2]] });
                dist = ray.distanceToPoint(worldPtTop);
                if (dist < minVertexDist) {
                    bestVertexSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id, normal: new THREE.Vector3(0,1,0) };
                    minVertexDist = dist;
                }
            }
        }
    };

    for (const shape of shapes) {
        const shapePos = new THREE.Vector3(...shape.position);
        if (shapePos.distanceTo(cursorPos) > SNAP_CULLING_DISTANCE) continue;
        if (shape.type === 'line' || shape.name === 'Edge') {
             const endpoints = getLineEndpoints(shape);
             if (endpoints) {
                 const edgeVec = new THREE.Vector3().subVectors(endpoints[1], endpoints[0]).normalize();
                 for(const ep of endpoints) {
                     const dist = ray.distanceToPoint(ep);
                     if (dist < minVertexDist) {
                         bestVertexSnap = { position: ep, type: 'endpoint', distance: dist, snapObjectId: shape.id, normal: edgeVec };
                         minVertexDist = dist;
                     }
                 }
                 continue; 
             }
        }
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        checkPoints(shape.points, shape, hasHeight, currentH);
        if (shape.holes) { shape.holes.forEach(hole => checkPoints(hole, shape, hasHeight, currentH)); }
    }

    if (!bestVertexSnap || bestVertexSnap.distance > 0.1) {
        const getTransformedVector = (x: number, y: number, z: number, shape: IShape) => {
            const v = new THREE.Vector3(x, y, z);
            v.set(v.x * shape.scale[0], v.y * shape.scale[1], v.z * shape.scale[2]);
            v.applyEuler(new THREE.Euler(...shape.rotation));
            v.add(new THREE.Vector3(...shape.position));
            return v;
        };

        const checkEdges = (pts: IPoint[], shape: IShape, hasHeight: boolean, currentH: number) => {
            const len = pts.length;
            for (let i = 0; i < len; i++) {
                if (!pts[i]) continue;
                const nextIdx = (i + 1) % len;
                if (!pts[nextIdx]) continue;
                const p1 = getTransformedVector(pts[i].x, 0, pts[i].z, shape);
                const p2 = getTransformedVector(pts[nextIdx].x, 0, pts[nextIdx].z, shape);
                const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                    const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                    const distMid = ray.distanceToPoint(mid);
                    const edgeVec = new THREE.Vector3().subVectors(v2, v1).normalize();
                    if (distMid < minEdgeDist) {
                        bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2], normal: edgeVec };
                        minEdgeDist = distMid;
                    }
                    const pointOnSegment = new THREE.Vector3();
                    const distSq = ray.distanceSqToSegment(v1, v2, undefined, pointOnSegment);
                    const distEdge = Math.sqrt(distSq);
                    if (distEdge < minEdgeDist) {
                         if (bestEdgeSnap?.type === 'midpoint' && bestEdgeSnap.distance < distEdge + 0.1) {} else {
                             bestEdgeSnap = { position: pointOnSegment, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2], normal: edgeVec };
                             minEdgeDist = distEdge;
                         }
                    }
                };
                checkSegment(p1, p2);
                if (hasHeight) {
                    const p1Top = getTransformedVector(pts[i].x, shape.height, pts[i].z, shape);
                    const p2Top = getTransformedVector(pts[nextIdx].x, shape.height, pts[nextIdx].z, shape);
                    checkSegment(p1Top, p2Top); 
                    checkSegment(p1, p1Top);
                }
            }
        };

        for (const shape of shapes) {
            const shapePos = new THREE.Vector3(...shape.position);
            if (shapePos.distanceTo(cursorPos) > SNAP_CULLING_DISTANCE) continue;
            const currentH = shape.height * shape.scale[1];
            const hasHeight = Math.abs(currentH) > 0.001;
            checkEdges(shape.points, shape, hasHeight, currentH);
            if (shape.holes) { shape.holes.forEach(hole => checkEdges(hole, shape, hasHeight, currentH)); }
        }
    }
    if (bestVertexSnap && bestEdgeSnap) {
        if (bestVertexSnap.distance < bestEdgeSnap.distance * 1.5) return bestVertexSnap;
        else return bestEdgeSnap;
    }
    if (bestVertexSnap) return bestVertexSnap;
    if (bestEdgeSnap) return bestEdgeSnap;
    return fallbackSnap;
};

// --- Render Components ---
const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => {
             if (!p) return new THREE.Vector3();
             return (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p));
        });
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);
    useLayoutEffect(() => { if (dashed && ref.current) ref.current.computeLineDistances(); });
    return (
        <line ref={ref as any}>
            <primitive object={geometry} attach="geometry" />
            {dashed ? ( <lineDashedMaterial color={color} dashSize={0.3} gapSize={0.2} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} /> ) : ( <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} /> )}
        </line>
    );
};

const InferenceGuideRenderer: React.FC<{ guide: InferenceGuide | null }> = ({ guide }) => {
    if (!guide) return null;
    const color = guide.type === 'x' ? '#ef4444' : '#22c55e';
    return ( <SimpleLine points={[guide.start, guide.end]} color={color} lineWidth={2} depthTest={false} opacity={0.8} /> );
};

const GuideLinesRenderer: React.FC<{ lines: IGuideLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return ( <group renderOrder={999}>{lines.map((line) => { const p1 = new THREE.Vector3(...line.points[0]); const p2 = new THREE.Vector3(...line.points[1]); const dir = new THREE.Vector3().subVectors(p2, p1).normalize(); const start = p1.clone().add(dir.clone().multiplyScalar(-5000)); const end = p1.clone().add(dir.clone().multiplyScalar(5000)); return ( <SimpleLine key={line.id} points={[start, end]} color="#4b5563" dashed lineWidth={1} depthTest={false} opacity={0.8} /> ); })}</group> );
};

