const DrawingPreview: React.FC<{ points: IPoint[]; cursorPos: THREE.Vector3; tool: ToolType; height: number; snapInfo: SnapResult | null }> = ({ points, cursorPos, tool, height, snapInfo }) => {
    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || tool === ToolType.ROTATE || tool === ToolType.HAND || tool === ToolType.DRAW_TEXT) return null;

    // Convert IPoint to Vector3 for rendering
    const renderedPoints = points.map(p => new THREE.Vector3(p.x, p.y, p.z));

    // Add current cursor position to preview
    const previewPoints = [...renderedPoints, cursorPos];

    if (tool === ToolType.DRAW_LINE) {
        return (
            <group>
                {renderedPoints.map((p, i) => (
                   <mesh key={i} position={p}><sphereGeometry args={[0.05]} /><meshBasicMaterial color="blue" /></mesh>
                ))}
                {previewPoints.length > 1 && <SimpleLine points={previewPoints} color="#3b82f6" lineWidth={2} depthTest={false} />}
            </group>
        );
    }

    if (tool === ToolType.DRAW_RECT && points.length > 0) {
        const start = points[0];
        const p1 = new THREE.Vector3(start.x, start.y, start.z);
        const p3 = cursorPos;
        // Simple bounding box style wireframe for rect preview
        return (
            <group>
                 <SimpleLine points={[p1, p3]} color="#3b82f6" dashed lineWidth={1} depthTest={false} />
                 <mesh position={p1}><sphereGeometry args={[0.05]} /><meshBasicMaterial color="blue" /></mesh>
                 <mesh position={p3}><sphereGeometry args={[0.05]} /><meshBasicMaterial color="blue" /></mesh>
                 <SimpleLine points={[
                     new THREE.Vector3(p1.x, p1.y, p1.z),
                     new THREE.Vector3(p3.x, p1.y, p1.z),
                     new THREE.Vector3(p3.x, p3.y, p3.z),
                     new THREE.Vector3(p1.x, p3.y, p3.z),
                     new THREE.Vector3(p1.x, p1.y, p1.z)
                 ]} color="#3b82f6" lineWidth={2} depthTest={false} />
            </group>
        );
    }

    if (tool === ToolType.DRAW_CIRCLE && points.length > 0) {
        const start = points[0];
        const center = new THREE.Vector3(start.x, start.y, start.z);
        const radius = center.distanceTo(cursorPos);
        return (
             <group>
                <mesh position={center}><sphereGeometry args={[0.05]} /><meshBasicMaterial color="blue" /></mesh>
                <SimpleLine points={[center, cursorPos]} color="#3b82f6" dashed lineWidth={1} />
                <SimpleLine points={createCirclePoints(radius).map(p => new THREE.Vector3(p.x + center.x, center.y, p.z + center.z))} color="#3b82f6" lineWidth={2} depthTest={false} />
             </group>
        );
    }

    if (tool === ToolType.DIMENSION && points.length > 0) {
         return (
             <group>
                {renderedPoints.map((p, i) => (
                   <mesh key={i} position={p}><sphereGeometry args={[0.05]} /><meshBasicMaterial color="orange" /></mesh>
                ))}
                <SimpleLine points={previewPoints} color="orange" dashed lineWidth={1} />
             </group>
         );
    }

    return null;
};

const InteractionLayer: React.FC<{
    shapes: IShape[];
    tool: ToolType;
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    isDragging: boolean;
    drawingHeight: number;
    typedInput: string;
    guideCreating: { active: boolean; start: THREE.Vector3; current: THREE.Vector3; edge: [THREE.Vector3, THREE.Vector3] | null };
    rotateState: RotateState;
    drawingNormal: THREE.Vector3;
    isGizmoDragging: boolean;
    inferenceGuide: InferenceGuide | null;
    setInferenceGuide: (g: InferenceGuide | null) => void;
    onMove: (e: ThreeEvent<PointerEvent>) => void;
    onPointerDown: (e: ThreeEvent<PointerEvent>) => void;
    onPointerUp: (e: ThreeEvent<PointerEvent>) => void;
    onClick: (e: ThreeEvent<MouseEvent>) => void;
}> = ({ shapes, tool, cursorPos, snapInfo, drawPoints, drawingHeight, typedInput, guideCreating, rotateState, isGizmoDragging, inferenceGuide, onMove, onPointerDown, onPointerUp, onClick }) => {

    const isInteractionMode = [ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DIMENSION, ToolType.GUIDE_LINE, ToolType.DRAW_TEXT].includes(tool);

    return (
        <group>
            {/* Invisible Ground Plane for event catching */}
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, -0.01, 0]} 
                onPointerMove={onMove} 
                onPointerDown={onPointerDown} 
                onPointerUp={onPointerUp}
                onClick={onClick}
                visible={true}
            >
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial color="pink" transparent opacity={0} depthWrite={false} />
            </mesh>

            {/* Visual Feedback Components */}
            {isInteractionMode && (
                <>
                    <DrawingPreview points={drawPoints} cursorPos={cursorPos} tool={tool} height={drawingHeight} snapInfo={snapInfo} />
                    {snapInfo && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}
                    <CursorTooltip text={snapInfo ? snapInfo.type : ''} position={cursorPos} type={snapInfo?.type} />
                </>
            )}

            {typedInput && <DynamicInputBox position={cursorPos} label="Length" value={typedInput} isTyping={!!typedInput} />}

            {inferenceGuide && <InferenceGuideRenderer guide={inferenceGuide} />}

            {/* Rotate Tool Visuals */}
            {tool === ToolType.ROTATE && rotateState.phase !== 'hover' && rotateState.pivot && (
                <group position={rotateState.pivot}>
                    {/* Pivot Point */}
                    <mesh><sphereGeometry args={[0.1]} /><meshBasicMaterial color="red" /></mesh>

                    {/* Protractor / Angle Visual */}
                    {rotateState.startVector && (
                        <>
                            <SimpleLine points={[new THREE.Vector3(), rotateState.startVector.clone().multiplyScalar(2)]} color="blue" lineWidth={2} />
                            {rotateState.phase === 'rotating' && (
                                <SimpleLine 
                                    points={[
                                        new THREE.Vector3(), 
                                        rotateState.startVector.clone().applyAxisAngle(new THREE.Vector3(0,1,0), rotateState.currentAngle).multiplyScalar(2)
                                    ]} 
                                    color="red" lineWidth={2} 
                                />
                            )}
                            {/* Arc */}
                            <mesh rotation={[-Math.PI/2, 0, 0]}>
                                <ringGeometry args={[1.8, 2, 32, 1, 0, rotateState.currentAngle]} />
                                <meshBasicMaterial color="blue" transparent opacity={0.3} side={THREE.DoubleSide} />
                            </mesh>
                        </>
                    )}
                </group>
            )}

            {/* Guide Creation Visuals */}
            {tool === ToolType.GUIDE_LINE && guideCreating.active && (
                <SimpleLine points={[guideCreating.start, guideCreating.current]} color="#4b5563" dashed lineWidth={1} />
            )}

        </group>
    );
};

