  // Grouping
  groupSelected: () => void;
  ungroupSelected: () => void;

  // Boolean Operations
  subtractSelected: () => void;
  booleanModal: IBooleanModalState;
  confirmBooleanOperation: (isContainer: boolean) => void;
  cancelBooleanOperation: () => void;

  // Layers
  activeLayerId: string;
  setActiveLayerId: (id: string) => void;
  addLayer: (name: string) => void;
  removeLayer: (id: string) => void;
  toggleLayerVisibility: (id: string) => void;
  updateLayerName: (id: string, name: string) => void;
  isLayerPanelOpen: boolean;
  setLayerPanelOpen: (open: boolean) => void;

  // History
  undo: () => void;
  redo: () => void;
  canUndo: boolean;
  canRedo: boolean;

  // File Ops
  saveProject: () => void;
  openProject: (file: File) => void;
  exportImage: () => void;

  // Utils
  formatValue: (val: number) => string;
  subscribeMeasurement: (callback: (val: string) => void) => () => void;
  setMeasurement: (val: string) => void;
  setCurrentView: (view: string) => void;
}

const AppContext = createContext<IAppContext | null>(null);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // State definitions
  const [shapes, setShapes] = useState<IShape[]>([]);
  const [layers, setLayers] = useState<ILayer[]>([
    { id: 'layer-1', name: '預設圖層', visible: true, locked: false }
  ]);
  const [activeLayerId, setActiveLayerId] = useState('layer-1');
  const [guideLines, setGuideLines] = useState<IGuideLine[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [unit, setUnit] = useState<'m' | 'cm'>('m');
  const [projectName, setProjectName] = useState('');
  const [isLayerPanelOpen, setLayerPanelOpen] = useState(false);
  const [booleanModal, setBooleanModal] = useState<IBooleanModalState>({ open: false, base: null, cutters: [] });
  const [wallThickness, setWallThickness] = useState(0.2); // Default 20cm

  // History State
  const [history, setHistory] = useState<{shapes: IShape[], layers: ILayer[], guideLines: IGuideLine[]}[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // Measurement subscription
  const measurementListeners = useRef<((val: string) => void)[]>([]);

  const _commitState = useCallback((newShapes: IShape[], newLayers: ILayer[], newGuideLines: IGuideLine[]) => {
      const newState = { shapes: newShapes, layers: newLayers, guideLines: newGuideLines };
      setHistory(prev => {
          const newHistory = prev.slice(0, historyIndex + 1);
          return [...newHistory, newState];
      });
      setHistoryIndex(prev => prev + 1);

      setShapes(newShapes);
      setLayers(newLayers);
      setGuideLines(newGuideLines);
  }, [historyIndex]);

  // Initial state commit
  useEffect(() => {
    if (history.length === 0) {
        const initialState = { shapes: [], layers: [{ id: 'layer-1', name: '預設圖層', visible: true, locked: false }], guideLines: [] };
        setHistory([initialState]);
        setHistoryIndex(0);
    }
  }, []);

  const undo = useCallback(() => {
      if (historyIndex > 0) {
          const prevIndex = historyIndex - 1;
          const prevState = history[prevIndex];
          setShapes(prevState.shapes);
          setLayers(prevState.layers);
          setGuideLines(prevState.guideLines);
          setHistoryIndex(prevIndex);
          setSelectedIds([]);
      }
  }, [history, historyIndex]);

  const redo = useCallback(() => {
      if (historyIndex < history.length - 1) {
          const nextIndex = historyIndex + 1;
          const nextState = history[nextIndex];
          setShapes(nextState.shapes);
          setLayers(nextState.layers);
          setGuideLines(nextState.guideLines);
          setHistoryIndex(nextIndex);
          setSelectedIds([]);
      }
  }, [history, historyIndex]);

  const addShape = useCallback((shape: IShape) => {
      _commitState([...shapes, shape], layers, guideLines);
  }, [shapes, layers, guideLines, _commitState]);

  const removeShape = useCallback((id: string) => {
      const newShapes = shapes.filter(s => s.id !== id);
      _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, _commitState]);

  const replaceShapes = useCallback((idsToRemove: string[], newShapes: IShape[]) => {
      const keptShapes = shapes.filter(s => !idsToRemove.includes(s.id));
      _commitState([...keptShapes, ...newShapes], layers, guideLines);
  }, [shapes, layers, guideLines, _commitState]);

  const addAIShapes = useCallback((items: AIGeneratedItem[]) => {
      const newShapes: IShape[] = items.map((item, idx) => ({
          id: `ai-${Date.now()}-${idx}`,
          layerId: activeLayerId,
          type: 'solid',
          points: [
              { x: item.x - item.width/2, y: 0, z: item.z - item.depth/2 },
              { x: item.x + item.width/2, y: 0, z: item.z - item.depth/2 },
              { x: item.x + item.width/2, y: 0, z: item.z + item.depth/2 },
              { x: item.x - item.width/2, y: 0, z: item.z + item.depth/2 },
          ],
          height: item.height,
          color: item.color,
          position: [0, 0, 0],
          rotation: [0, 0, 0],
          scale: [1, 1, 1],
          name: item.name
      }));
      _commitState([...shapes, ...newShapes], layers, guideLines);
  }, [shapes, layers, guideLines, activeLayerId, _commitState]);

  const updateShape = useCallback((id: string, changes: Partial<IShape>) => {
      const newShapes = shapes.map(s => s.id === id ? { ...s, ...changes } : s);
      _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, _commitState]);

  const updateShapes = useCallback((updates: { id: string, changes: Partial<IShape> }[]) => {
      const newShapes = shapes.map(s => {
          const update = updates.find(u => u.id === s.id);
          return update ? { ...s, ...update.changes } : s;
      });
      _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, _commitState]);

  const removeSelected = useCallback(() => {
      const newShapes = shapes.filter(s => !selectedIds.includes(s.id));
      _commitState(newShapes, layers, guideLines);
      setSelectedIds([]);
  }, [shapes, layers, guideLines, selectedIds, _commitState]);

  const copySelected = useCallback(() => {
      // Basic copy implementation
      const toCopy = shapes.filter(s => selectedIds.includes(s.id));
      const newShapes = toCopy.map(s => ({
          ...s,
          id: `copy-${Date.now()}-${s.id}`,
          position: [s.position[0] + 0.5, s.position[1], s.position[2] + 0.5] as [number, number, number],
          name: `${s.name} (複製)`
      }));
      _commitState([...shapes, ...newShapes], layers, guideLines);
      setSelectedIds(newShapes.map(s => s.id));
  }, [shapes, layers, guideLines, selectedIds, _commitState]);

  const selectShape = useCallback((id: string, multi: boolean) => {
      if (multi) {
          setSelectedIds(prev => prev.includes(id) ? prev.filter(pid => pid !== id) : [...prev, id]);
      } else {
          setSelectedIds([id]);
      }
  }, []);

  const clearScene = useCallback(() => {
      _commitState([], layers, []);
      setSelectedIds([]);
  }, [layers, _commitState]);

  const addGuideLine = useCallback((line: IGuideLine) => {
      _commitState(shapes, layers, [...guideLines, line]);
  }, [shapes, layers, guideLines, _commitState]);

  const clearGuideLines = useCallback(() => {
      _commitState(shapes, layers, []);
  }, [shapes, layers, _commitState]);

  const groupSelected = useCallback(() => {
      if (selectedIds.length < 2) return;
      const groupId = `group-${Date.now()}`;
      const newShapes = shapes.map(s => selectedIds.includes(s.id) ? { ...s, groupId } : s);
      _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, selectedIds, _commitState]);

  const ungroupSelected = useCallback(() => {
      const newShapes = shapes.map(s => selectedIds.includes(s.id) ? { ...s, groupId: undefined } : s);
      _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, selectedIds, _commitState]);

  const subtractSelected = useCallback(() => {
      if (selectedIds.length < 2) return;
      // Assume first selected is base (or last selected? usually last selected is active)
      // Logic: Selected objects -> 1 Base, others are Cutters.
      // We open modal to ask user confirmation and type.
      const baseId = selectedIds[0]; // Simplification
      const base = shapes.find(s => s.id === baseId);
      const cutters = shapes.filter(s => selectedIds.includes(s.id) && s.id !== baseId);

      if (base && cutters.length > 0) {
          setBooleanModal({ open: true, base, cutters });
      }
  }, [shapes, selectedIds]);

  const confirmBooleanOperation = useCallback((isContainer: boolean) => {
      const { base, cutters } = booleanModal;
      if (!base || cutters.length === 0) {
          setBooleanModal({ open: false, base: null, cutters: [] });
          return;
      }

      // 2. Prepare Base Matrix for inverse transformation
      const baseObj = new THREE.Object3D();
      baseObj.position.set(...base.position);
      baseObj.rotation.set(...base.rotation);
      baseObj.scale.set(...base.scale);
      baseObj.updateMatrixWorld();
      const baseInvMatrix = baseObj.matrixWorld.clone().invert();

      // 3. Transform all cutters into Base's local coordinate system
      const newHoles: IPoint[][] = [...(base.holes || [])];

      cutters.forEach(cutter => {
          const cutterObj = new THREE.Object3D();
          cutterObj.position.set(...cutter.position);
          cutterObj.rotation.set(...cutter.rotation);
          cutterObj.scale.set(...cutter.scale);
          cutterObj.updateMatrixWorld();

          // Transform points
          const holePoly: IPoint[] = cutter.points.map(p => {
              const vec = new THREE.Vector3(p.x, 0, p.z);
              // To World
              vec.applyMatrix4(cutterObj.matrixWorld);
              // To Base Local
              vec.applyMatrix4(baseInvMatrix);
              return { x: vec.x, y: 0, z: vec.z };
          });

          newHoles.push(holePoly);
      });

      // 4. Update Base shape with new holes
      const updatedBase = {
          ...base,
          holes: newHoles
      };

      // 5. Prepare Final Shapes
      const cutterIds = cutters.map(c => c.id);

      // We must use the current `shapes` state for the final filter to ensure we don't revert other changes
      let finalShapes = shapes.filter(s => !cutterIds.includes(s.id) && s.id !== base.id);

      if (isContainer) {
          // If container, we keep cutters but modify them to be thin "floors"
          // This simulates the "blind hole" effect
          const newGroupId = base.groupId || `group-${Date.now()}`;
          updatedBase.groupId = newGroupId;

          const CONTAINER_BOTTOM_THICKNESS = 0.1; // 10cm bottom

          const bottoms: IShape[] = cutters.map(c => ({
              ...c,
              id: `bottom-${c.id}`,
              type: 'solid',
              height: CONTAINER_BOTTOM_THICKNESS, // Simulate stopping the push/pull before the end
              // Align with base bottom
              position: [c.position[0], base.position[1], c.position[2]] as [number, number, number], 
              name: `${c.name} (底)`,
              groupId: newGroupId, // Auto group with base
              layerId: base.layerId,
              color: base.color // Match base color for seamless look
          }));

          finalShapes = [...finalShapes, updatedBase, ...bottoms];
      } else {
          finalShapes = [...finalShapes, updatedBase];
      }

      _commitState(finalShapes, layers, guideLines);
      setSelectedIds([base.id]);
      setBooleanModal({ open: false, base: null, cutters: [] });

  }, [booleanModal, shapes, layers, guideLines, historyIndex, _commitState]);

  const cancelBooleanOperation = useCallback(() => {
      setBooleanModal({ open: false, base: null, cutters: [] });
  }, []);

  const addLayer = useCallback((name: string) => {
      const newLayer = { id: `layer-${Date.now()}`, name, visible: true, locked: false };
      _commitState(shapes, [...layers, newLayer], guideLines);
      setActiveLayerId(newLayer.id);
  }, [shapes, layers, guideLines, _commitState]);

  const removeLayer = useCallback((id: string) => {
      if (layers.length <= 1) return;
      const newLayers = layers.filter(l => l.id !== id);
      // Move shapes to default layer or delete? Assume delete for now or keep in limbo. 
      // Better: prevent delete if shapes exist or move to active.
      const fallbackId = newLayers[0].id;
      const newShapes = shapes.map(s => s.layerId === id ? { ...s, layerId: fallbackId } : s);
      _commitState(newShapes, newLayers, guideLines);
      if (activeLayerId === id) setActiveLayerId(fallbackId);
  }, [shapes, layers, guideLines, activeLayerId, _commitState]);

  const toggleLayerVisibility = useCallback((id: string) => {
      const newLayers = layers.map(l => l.id === id ? { ...l, visible: !l.visible } : l);
      // We don't commit history for visibility toggles usually, but let's do it for consistency or skip _commitState if valid
      setLayers(newLayers);
  }, [layers]);

  const updateLayerName = useCallback((id: string, name: string) => {
      const newLayers = layers.map(l => l.id === id ? { ...l, name } : l);
      setLayers(newLayers);
  }, [layers]);

  const saveProject = useCallback(() => {
      const data = JSON.stringify({ shapes, layers, guideLines, version: 1 }, null, 2);
      const blob = new Blob([data], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${projectName || 'project'}.json`;
      a.click();
  }, [shapes, layers, guideLines, projectName]);

  const openProject = useCallback((file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              const data = JSON.parse(e.target?.result as string);
              if (data.shapes && data.layers) {
                  _commitState(data.shapes, data.layers, data.guideLines || []);
              }
          } catch (err) {
              console.error(err);
              alert("無法開啟檔案");
          }
      };
      reader.readAsText(file);
  }, [_commitState]);

  const exportImage = useCallback(() => {
      // Logic to grab canvas data url
      const canvas = document.querySelector('canvas');
      if (canvas) {
          const url = canvas.toDataURL('image/png');
          const a = document.createElement('a');
          a.href = url;
          a.download = `${projectName || 'screenshot'}.png`;
          a.click();
      }
  }, [projectName]);

  const formatValue = useCallback((val: number) => {
      if (unit === 'cm') return `${(val * 100).toFixed(1)} cm`;
      return `${val.toFixed(3)} m`;
  }, [unit]);

  const subscribeMeasurement = useCallback((callback: (val: string) => void) => {
      measurementListeners.current.push(callback);
      return () => {
          measurementListeners.current = measurementListeners.current.filter(cb => cb !== callback);
      };
  }, []);

  const setMeasurement = useCallback((val: string) => {
      measurementListeners.current.forEach(listener => listener(val));
  }, []);

  const setCurrentView = useCallback((view: string) => {
      // This is a placeholder as actual camera control might need ref to controls or using event bus
      console.log('Set view', view);
  }, []);

  return (
    <AppContext.Provider value={{
      tool, setTool,
      shapes, layers, guideLines, selectedIds,
      unit, setUnit,
      projectName, setProjectName,
      wallThickness, setWallThickness,
      addShape, addAIShapes, updateShape, updateShapes, removeShape, replaceShapes, removeSelected, copySelected, selectShape, clearScene,
      addGuideLine, clearGuideLines,
      groupSelected, ungroupSelected, subtractSelected,
      booleanModal, confirmBooleanOperation, cancelBooleanOperation,
      activeLayerId, setActiveLayerId, addLayer, removeLayer, toggleLayerVisibility, updateLayerName,
      isLayerPanelOpen, setLayerPanelOpen,
      undo, redo, canUndo: historyIndex > 0, canRedo: historyIndex < history.length - 1,
      saveProject, openProject, exportImage,
      formatValue, subscribeMeasurement, setMeasurement, setCurrentView
    }}>
      {children}
    </AppContext.Provider>
  );
};
